/**
 * HR-3 / #4220: delete-branch-stacked-pr-guard must never put a branch name
 * into a shell string.
 *
 * `git check-ref-format` rejects spaces, not `;` / backticks / `$(...)`, so a
 * fork PR can carry `evil;touch /tmp/pwned` as headRefName. That name used to
 * reach `execSync(\`gh pr list --base ${headBranch}\`)` (same class as the
 * worktree-merge-verifier RCE in #3365). Production already uses
 * `execFileSync(file, args)`; this suite locks the argv shape so an
 * `execSync` / template-literal regression cannot land unnoticed.
 *
 * Grounding: Vitest vi.mock / toHaveBeenCalledWith (vitest v4.0.7 docs via
 * context7 /vitest-dev/vitest). Sibling style: auto-lint.test.ts,
 * issue-context-injector.test.ts.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';

const mockExecFileSync = vi.fn();
const mockExecSync = vi.fn();

vi.mock('node:child_process', () => ({
  execFileSync: (...args: unknown[]) => mockExecFileSync(...args),
  execSync: (...args: unknown[]) => mockExecSync(...args),
}));

import {
  resolveHeadBranch,
  findDependentPRs,
} from '../../../pretool/bash/delete-branch-stacked-pr-guard.js';

// Space is illegal in a git ref; `;` is not. The spaced form is still what a
// hostile `gh pr view` can return as headRefName and what findDependentPRs
// must pass as a single --base argv slot. The no-space form fits PR_REF_RE's
// `\S+` capture when the merge positional itself is the weaponized ref.
const EVIL_BRANCH = 'evil;touch /tmp/pwned';
const EVIL_REF = 'evil;touch_/tmp/pwned';
const PROJECT = '/tmp/ork-hr3-proj';

/** Every child_process call must be (file, string[], opts): never a shell string. */
function assertArgvOnlyCalls(calls: unknown[][], forbiddenInFile = EVIL_BRANCH): void {
  for (const call of calls) {
    expect(typeof call[0]).toBe('string');
    expect(Array.isArray(call[1])).toBe(true);
    // First arg must be a bare binary name / path, not a full shell command line
    expect(String(call[0])).not.toMatch(/[;|&`$]/);
    expect(String(call[0])).not.toContain(forbiddenInFile);
  }
}

describe('HR-3 delete-branch-stacked-pr-guard shell safety', () => {
  beforeEach(() => {
    mockExecFileSync.mockReset();
    mockExecSync.mockReset();
  });

  it('never calls execSync', () => {
    mockExecFileSync.mockReturnValue('feat/legit\n');
    resolveHeadBranch(PROJECT, `gh pr merge ${EVIL_REF} --squash --delete-branch`);

    mockExecFileSync.mockReturnValue('[]');
    findDependentPRs(PROJECT, EVIL_BRANCH);

    expect(mockExecSync).not.toHaveBeenCalled();
  });

  it('resolveHeadBranch passes a metachar PR ref as one argv entry, not a shell string', () => {
    // Arrange: hostile name is the merge positional; gh pr view gets it as argv[2].
    mockExecFileSync.mockReturnValue('feat/legit\n');

    // Act
    const head = resolveHeadBranch(
      PROJECT,
      `gh pr merge ${EVIL_REF} --squash --delete-branch`,
    );

    // Assert
    expect(head).toBe('feat/legit');
    expect(mockExecSync).not.toHaveBeenCalled();
    expect(mockExecFileSync).toHaveBeenCalledWith(
      'gh',
      ['pr', 'view', EVIL_REF, '--json', 'headRefName', '-q', '.headRefName'],
      expect.objectContaining({ cwd: PROJECT }),
    );
    assertArgvOnlyCalls(mockExecFileSync.mock.calls, EVIL_REF);
  });

  it('findDependentPRs passes a metachar head branch as --base argv entry', () => {
    // Arrange: EVIL_BRANCH matches the audit payload (`evil;touch /tmp/pwned`)
    mockExecFileSync.mockReturnValue('[{"number":7,"title":"stacked"}]');

    // Act
    const deps = findDependentPRs(PROJECT, EVIL_BRANCH);

    // Assert
    expect(deps).toEqual([{ number: 7, title: 'stacked' }]);
    expect(mockExecSync).not.toHaveBeenCalled();
    expect(mockExecFileSync).toHaveBeenCalledWith(
      'gh',
      [
        'pr',
        'list',
        '--base',
        EVIL_BRANCH,
        '--state',
        'open',
        '--json',
        'number,title',
        '--limit',
        '20',
      ],
      expect.objectContaining({ cwd: PROJECT }),
    );
    // The evil string is exactly one argv slot, not concatenated into argv[0]
    const args = mockExecFileSync.mock.calls[0]?.[1] as string[];
    expect(args).toContain(EVIL_BRANCH);
    expect(args.filter(a => a === EVIL_BRANCH)).toHaveLength(1);
    assertArgvOnlyCalls(mockExecFileSync.mock.calls);
  });
});
